class Solution {
public:
    string numberToWords(int num) {
        if (num == 0) return "Zero";

        vector<string> ones = {"", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine",
                               "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
                               "Seventeen", "Eighteen", "Nineteen"};
        vector<string> tens = {"", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"};

        string result;
        long long scales[] = {1000000000LL, 1000000LL, 1000LL, 1LL};
        string scaleNames[] = {"Billion", "Million", "Thousand", ""};

        for (int i = 0; i < 4; i++) {
            int chunk = (num / scales[i]) % 1000;
            if (chunk > 0) {
                if (!result.empty()) result += " ";
                result += helper(chunk, ones, tens);
                if (!scaleNames[i].empty()) {
                    result += " " + scaleNames[i];
                }
            }
        }

        return result;
    }

private:
    string helper(int num, vector<string>& ones, vector<string>& tens) {
        string result;
        if (num >= 100) {
            result += ones[num / 100] + " Hundred";
            num %= 100;
        }
        if (num >= 20) {
            if (!result.empty()) result += " ";
            result += tens[num / 10];
            num %= 10;
        }
        if (num > 0) {
            if (!result.empty()) result += " ";
            result += ones[num];
        }
        return result;
    }
};
